  border-color:#444749;
  box-shadow:inset 0 0 0 3px #1C1F21;
}
.la-input-row:before,
.la-chat-input-form .la-input-row:before{
  content:'';
  position:absolute;
  inset:-1px;
  border-radius:inherit;
  padding:2px;
  background:conic-gradient(from var(--la-orbit, 0deg),transparent 0deg,#D5AD4B 16deg,#FFF3C4 20deg,transparent 26deg,transparent 180deg,#D5AD4B 196deg,#FFF3C4 200deg,transparent 206deg);
  -webkit-mask:linear-gradient(#fff 0 0) content-box,linear-gradient(#fff 0 0);
  -webkit-mask-composite:xor;
  mask:linear-gradient(#fff 0 0) content-box,linear-gradient(#fff 0 0);
  mask-composite:exclude;
  pointer-events:none;
  animation:la-orbit 7s linear infinite;
}
.lc-root.is-dark .la-input-row:before,
.lc-panel.is-dark .la-input-row:before,
.lc-root.is-dark .la-chat-input-form .la-input-row:before,
