.lc-pl-lender-card:hover{border-color:var(--la-line);box-shadow:none}
.lc-gold-submit-top{display:flex;align-items:center;gap:12px;margin-bottom:14px}
.lc-gold-submit-logo{position:relative;width:56px;height:36px;display:grid;place-items:center;border:1px solid var(--la-line);border-radius:8px;background:#fff;overflow:hidden;padding:4px;flex:none}
.lc-gold-submit-logo img{position:absolute;inset:4px;width:calc(100% - 8px)!important;height:calc(100% - 8px)!important;max-width:none!important;object-fit:contain;object-position:center}
.lc-gold-submit-lender{flex:1;min-width:0;font-size:14px;font-weight:600;color:var(--la-ink)}
.lc-best-tag{display:inline-block;flex:none;font-size:9px;font-weight:600;letter-spacing:.02em;text-transform:uppercase;padding:3px 8px;border-radius:100px;background:var(--la-soft);color:var(--la-gold)}
.lc-gold-submit-main{margin-bottom:16px}
.lc-gold-submit-amount{font:400 28px/1.2 var(--serif);color:var(--la-gold)}
.lc-gold-submit-rate{font-size:12.5px;color:var(--la-muted);margin-top:2px}
.lc-gold-submit-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;border-top:1px solid var(--la-line);padding-top:14px;margin-bottom:16px}
